 1| /**
 2|  * combine-checks: brings the answers of the two side-by-side checks together.
 3|  *
 4|  * Why it exists: each side-by-side check writes in its own space
 5|  * (`runs.<check id>.<key>`), so a later step cannot see it as a plain key.
 6|  * This step copies each answer to a plain key the approval reads.
 7|  * Example: `runs.check-stock.stockOk = true` → `stockOk = true`.
 8|  */
 9| 
10| export const purpose = 'Copy the stock and credit answers to the keys the approval reads.';
11| 
12| /** @param {any} scope */
13| export function run(scope) {
14|   scope.stockOk = scope.$read('runs.check-stock.stockOk');
15|   scope.shortSkus = scope.$read('runs.check-stock.shortSkus');
16|   scope.creditOk = scope.$read('runs.check-credit.creditOk');
17| }
