 1| /**
 2|  * find-rate (inside the tax sub-flowchart): the tax rate of the region.
 3|  *
 4|  * Example: `region = 'south'` → `rate = 0.06`; an unlisted region → the default rate.
 5|  */
 6| import { DEFAULT_TAX_RATE, TAX_RATES } from '../../../../data/tax-rates.mjs';
 7| 
 8| export const purpose = 'Find the tax rate of the region.';
 9| 
10| /** @param {any} scope */
11| export function run(scope) {
12|   scope.rate = TAX_RATES[scope.region] ?? DEFAULT_TAX_RATE;
13| }
