 1| /**
 2|  * grand-total: what the customer pays: the goods after discounts, plus tax,
 3|  * plus shipping.
 4|  *
 5|  * Example: net 450, tax 36, shipping 0 → `grandTotal = 486`.
 6|  */
 7| import { roundCents } from '../../money.mjs';
 8| 
 9| export const purpose = 'Add tax and shipping to the discounted amount.';
10| 
11| /** @param {any} scope */
12| export function run(scope) {
