 1| /**
 2|  * net-amount: what the goods cost after every discount. Tax and shipping
 3|  * are worked out from this amount.
 4|  *
 5|  * Example: subtotal 500, coupon 40, loyalty 10 → `netAmount = 450`.
 6|  */
 7| import { roundCents } from '../../money.mjs';
 8| 
 9| export const purpose = 'Take the discounts off the subtotal.';
10| 
11| /** @param {any} scope */
12| export function run(scope) {
13|   scope.netAmount = roundCents(scope.subtotal - scope.discount - scope.loyaltyDiscount);
